export function toAppData(appData) {
    return {
        id: appData.id,
        name: appData.name,
        website: null,
        redirect_uri: appData.callbackUrl,
        client_id: '',
        client_secret: appData.secret ?? '',
        url: null,
        session_token: null
    };
}
export function toTokenData(tokenData) {
    return {
        access_token: tokenData.accessToken,
        token_type: 'Firefish',
        scope: null,
        created_at: null,
        expires_in: null,
        refresh_token: null
    };
}
